html:
{% set rows = doc.pricing_list or [] %}
{% set total_cost = rows | sum(attribute='ammount') %}
{% set total_sell = rows | sum(attribute='selling_ammount') %}

<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #222; }
  .cs-header { display: flex; justify-content: space-between; align-items: flex-start;
               border-bottom: 2px solid #1a3a5c; padding-bottom: 10px; margin-bottom: 14px; }
  .cs-title { font-size: 20px; font-weight: 700; color: #1a3a5c; }
  .cs-meta { font-size: 11px; color: #555; margin-top: 4px; }
  .cs-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 24px;
                  margin-bottom: 16px; font-size: 11.5px; }
  .cs-info-grid .lbl { color: #888; font-weight: 600; text-transform: uppercase;
                       font-size: 10px; letter-spacing: .04em; }
  .cs-info-grid .val { font-weight: 600; color: #1a3a5c; }
  table.pricing { width: 100%; border-collapse: collapse; margin-bottom: 12px; font-size: 11.5px; }
  table.pricing thead tr { background: #1a3a5c; color: #fff; }
  table.pricing thead th { padding: 6px 8px; text-align: left; font-size: 10.5px;
                           font-weight: 600; letter-spacing: .03em; }
  table.pricing thead th.r { text-align: right; }
  table.pricing tbody tr { border-bottom: 1px solid #e5e7eb; }
  table.pricing tbody tr:nth-child(even) { background: #f8fafc; }
  table.pricing tbody td { padding: 6px 8px; }
  table.pricing tbody td.r { text-align: right; font-family: monospace; }
  table.pricing tfoot tr { background: #1a3a5c; color: #fff; font-weight: 700; }
  table.pricing tfoot td { padding: 7px 8px; }
  table.pricing tfoot td.r { text-align: right; font-family: monospace; }
  .cs-footer { margin-top: 18px; font-size: 10px; color: #888;
               border-top: 1px solid #e5e7eb; padding-top: 8px; text-align: center; }
  .badge { display: inline-block; padding: 1px 8px; border-radius: 10px;
           font-size: 10px; font-weight: 700; }
  .badge-blue  { background: #dbeafe; color: #1e40af; }
  .badge-green { background: #dcfce7; color: #166534; }
</style>

<div class='cs-header'>
  <div>
    <div class='cs-title'>Cost Sheet</div>
    <div class='cs-meta'>{{ doc.name }} &nbsp;|&nbsp; {{ frappe.format(doc.creation, 'Date') }}</div>
  </div>
  <div style='text-align:right'>
    <div style='font-size:13px;font-weight:700;color:#1a3a5c'>{{ doc.customer_name or '' }}</div>
    {% if doc.inquiry %}
    <div class='cs-meta'>Inquiry: {{ doc.inquiry }}</div>
    {% endif %}
  </div>
</div>

<div class='cs-info-grid'>
  <div>
    <div class='lbl'>Subject / Product</div>
    <div class='val'>{{ doc.subject or '—' }}</div>
  </div>
  <div>
    <div class='lbl'>Item Group</div>
    <div class='val'>{{ doc.item_group or '—' }}</div>
  </div>
  <div>
    <div class='lbl'>Colours</div>
    <div class='val'>{{ doc.colour or 0 }}</div>
  </div>
  <div>
    <div class='lbl'>TIEP Status</div>
    <div class='val'>{{ doc.tiep or '—' }}</div>
  </div>
  {% if doc.sales_person %}
  <div>
    <div class='lbl'>Sales Person</div>
    <div class='val'>{{ doc.sales_person }}</div>
  </div>
  {% endif %}
</div>

<table class='pricing'>
  <thead>
    <tr>
      <th>Group</th>
      <th>Item Name</th>
      <th class='r'>Qty</th>
      <th class='r'>Unit Cost (LKR)</th>
      <th class='r'>Cost Amount (LKR)</th>
      <th class='r'>Selling Price (LKR)</th>
      <th class='r'>Selling Amount (LKR)</th>
    </tr>
  </thead>
  <tbody>
    {% for row in rows %}
    <tr>
      <td>{{ row.group_name or '' }}</td>
      <td><b>{{ row.item_name or '' }}</b></td>
      <td class='r'>{{ '{:,.0f}'.format(row.qty or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.unit_price or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.ammount or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.selling_unit_price or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.selling_ammount or 0) }}</td>
    </tr>
    {% endfor %}
  </tbody>
  <tfoot>
    <tr>
      <td colspan='4' style='text-align:right;letter-spacing:.03em'>TOTAL</td>
      <td class='r'>{{ '{:,.2f}'.format(total_cost) }}</td>
      <td></td>
      <td class='r'>{{ '{:,.2f}'.format(total_sell) }}</td>
    </tr>
  </tfoot>
</table>

<div class='cs-footer'>
  Generated from Savinda Pricing Calculator &nbsp;&bull;&nbsp; {{ doc.name }}
  &nbsp;&bull;&nbsp; Status: <b>Submitted</b>
</div>

{% set state = frappe.parse_json(doc.ui_state) if doc.ui_state else {} %}
{% set form = state.get('form', {}) %}
{% set calc = state.get('calc_result', {}) %}
{% set sheet = calc.get('sheet', {}) %}
{% set pricing = calc.get('pricing', {}) %}
{% set group_totals = calc.get('group_totals', {}) %}
{% set cost_rows = calc.get('cost_rows', []) %}
{% set is_flexo = (doc.pricing_type or 'Offset') == 'Flexo' %}

{# ─── group cost rows ─── #}
{% set mat_rows   = cost_rows | selectattr('cost_group','in',['Material','material'])   | list %}
{% set prep_rows  = cost_rows | selectattr('cost_group','in',['Preparation','preparation']) | list %}
{% set prod_rows  = cost_rows | selectattr('cost_group','in',['Production','production'])   | list %}

{# ─── helpers ─── #}
{% macro desc(row) %}
  {%- if row.get('spec_name') == 'Base Material' -%}
    {{ row.get('selected_item_name') or row.get('cost_fact') }}
  {%- elif row.get('selected_item_name') and row.get('selected_item_name') != row.get('cost_fact') -%}
    {{ row.get('cost_fact') }}: {{ row.get('selected_item_name') }}
  {%- else -%}
    {{ row.get('cost_fact') }}
  {%- endif %}
{% endmacro %}

{% macro fmt(v) %}{{ '{:,.2f}'.format((v or 0) | float) }}{% endmacro %}
{% macro fmtq(v) %}{{ '{:,.4g}'.format((v or 0) | float) }}{% endmacro %}

{# ─── foil detection for Flexo ─── #}
{% set has_gold = [] %}{% set has_silver = [] %}
{% for spec in state.get('selected_specs', []) %}
  {% for foil in (spec.get('machine_assignment') or {}).get('foils', []) %}
    {% if 'gold' in (foil.get('foil_name','') | lower) %}{% set _ = has_gold.append(1) %}{% endif %}
    {% if 'silver' in (foil.get('foil_name','') | lower) %}{% set _ = has_silver.append(1) %}{% endif %}
  {% endfor %}
{% endfor %}

{# ─── breakdown description from Cost Item Calculation ─── #}
{% set ci_calc = frappe.db.get_value('Cost Item Calculation',
    {'calculation_breakdown': doc.name}, ['description','parent'], as_dict=1) %}
{% set breakdown_name = '' %}
{% if ci_calc %}
  {% set ci_name = frappe.db.get_value('cost Item', ci_calc.parent, 'cost_item_name') %}
  {% set breakdown_name = ci_name or ci_calc.description or ci_calc.parent %}
{% endif %}

{# ─── pricing values ─── #}
{% set item_qty    = (doc.item_qty or 0) | float %}
{% set grand_total = (group_totals.get('grand') or 0) | float %}
{% set unit_cost   = (pricing.get('unit_cost') or 0) | float %}
{% set sscl_amt    = (pricing.get('sscl') or 0) | float %}
{% set vat_amt     = (pricing.get('vat') or 0) | float %}
{% set sell_unit   = (pricing.get('sell_unit') or 0) | float %}
{% set sell_total  = (pricing.get('sell_total') or 0) | float %}
{% set mat_contrib = (pricing.get('mat_contrib') or 0) | float %}
{% set profit_margin = (doc.profit_margin or 0) | float %}

<style>
  * { box-sizing: border-box; }
  body, .pcs { font-family: Arial, Helvetica, sans-serif; font-size: 11.5px; color: #222; }
  .pcs-meta { text-align: right; font-size: 9.5px; color: #666; margin-bottom: 4px; }
  .pcs-co { display: flex; align-items: flex-end; gap: 10px; margin-bottom: 6px; }
  .pcs-co-name { font-size: 12px; font-weight: bold; }
  .pcs-title { text-align: center; font-size: 14px; font-weight: bold; margin: 8px 0 12px; letter-spacing: .3px; }
  .info-tbl { margin-bottom: 14px; }
  .info-tbl td { padding: 2px 4px; vertical-align: top; }
  .info-tbl td:first-child { font-weight: bold; white-space: nowrap; padding-right: 8px; }
  .cost-tbl { width: 100%; border-collapse: collapse; margin-bottom: 14px; font-size: 11.5px; }
  .cost-tbl th { background: #2b2b2b; color: #fff; padding: 6px 8px; text-align: center; font-size: 11px; border: 1px solid #555; }
  .cost-tbl th:first-child { text-align: left; }
  .cost-tbl td { padding: 4px 8px; border-bottom: 1px solid #e8e8e8; }
  .cost-tbl td.r { text-align: right; }
  .cost-tbl td.c { text-align: center; }
  .grp-row td { background: #e07b00; color: #fff; font-weight: bold; padding: 5px 8px; }
  .grp-total { text-align: right; font-weight: bold; }
  .cost-tbl tr:nth-child(even) td { background: #fafafa; }
  .cost-tbl .grp-row td { background: #e07b00 !important; }
  .sum-wrap { display: flex; justify-content: space-between; margin-bottom: 14px; gap: 20px; }
  .sum-left { flex: 1; font-size: 11.5px; }
  .sum-right { width: 280px; }
  .sum-right table { width: 100%; border-collapse: collapse; }
  .sum-right td { padding: 3px 6px; font-size: 11.5px; }
  .sum-right td:last-child { text-align: right; font-weight: 600; white-space: nowrap; }
  .sum-right .sum-sep td { border-top: 1px solid #ccc; }
  .remarks-lbl { font-weight: bold; margin-top: 10px; margin-bottom: 4px; }
  .mat-tbl { width: 100%; border-collapse: collapse; font-size: 11px; }
  .mat-tbl th { background: #444; color: #fff; padding: 5px 8px; text-align: left; border: 1px solid #666; }
  .mat-tbl td { padding: 4px 8px; border: 1px solid #ddd; }
</style>

<div class="pcs">
  <div class="pcs-meta">
    Created at {{ frappe.format_date(doc.creation) }} by {{ frappe.db.get_value('User', doc.owner, 'full_name') or doc.owner }}<br>
    Updated at {{ frappe.format_date(doc.modified) }} by {{ frappe.db.get_value('User', doc.modified_by, 'full_name') or doc.modified_by }}
  </div>

  <div class="pcs-co">
    {% set logo = frappe.db.get_value('Company', frappe.defaults.get_defaults().get('company'), 'company_logo') %}
    {% if logo %}<img src="{{ logo }}" style="height:55px;">{% endif %}
    <div>
      <div class="pcs-co-name">Savinda Graphic Systems (Pvt) Ltd.</div>
    </div>
  </div>

  <div class="pcs-title">Product Costing Summary</div>

  {# ─── Header info ─── #}
  <table class="info-tbl">
    <tr><td>Sales Inquiry</td><td>: {{ doc.ref or '' }}</td></tr>
    <tr><td>Customer</td><td>: {{ doc.customer_name or '' }}</td></tr>
    <tr><td>Inquiry Breakdown</td><td>: {{ breakdown_name }}</td></tr>
    <tr><td>Breakdown Quantity</td><td>: {{ doc.item_qty | int }}</td></tr>
  </table>

  {# ─── Cost table ─── #}
  <table class="cost-tbl">
    <thead>
      <tr>
        <th style="width:45%">DESCRIPTION</th>
        <th style="width:15%">ESTIMATED QTY.</th>
        <th style="width:20%">UNIT PRICE(LKR)</th>
        <th style="width:20%">AMOUNT(LKR)</th>
      </tr>
    </thead>
    <tbody>
      {# Material Costs #}
      {% if mat_rows %}
      <tr class="grp-row">
        <td>Material Costs</td><td></td><td></td>
        <td class="r">{{ fmt(group_totals.get('material', 0)) }}</td>
      </tr>
      {% for row in mat_rows %}
      <tr>
        <td>{{ desc(row) }}</td>
        <td class="c">{{ fmtq(row.get('req_qty', 0)) }}</td>
        <td class="r">{{ fmt(row.get('rate', 0)) if row.get('rate', 0) else '' }}</td>
        <td class="r">{{ fmt(row.get('amount', 0)) }}</td>
      </tr>
      {% endfor %}
      {% endif %}

      {# Preparation Costs #}
      {% if prep_rows %}
      <tr class="grp-row">
        <td>Preparation Costs</td><td></td><td></td>
        <td class="r">{{ fmt(group_totals.get('preparation', 0)) }}</td>
      </tr>
      {% for row in prep_rows %}
      <tr>
        <td>{{ desc(row) }}</td>
        <td class="c">{{ fmtq(row.get('req_qty', 0)) }}</td>
        <td class="r">{{ fmt(row.get('rate', 0)) if row.get('rate', 0) else '' }}</td>
        <td class="r">{{ fmt(row.get('amount', 0)) }}</td>
      </tr>
      {% endfor %}
      {% endif %}

      {# Production / Over Head Costs #}
      {% if prod_rows %}
      <tr class="grp-row">
        <td>{{ 'Over Head Costs' if is_flexo else 'Production Costs' }}</td><td></td><td></td>
        <td class="r">{{ fmt(group_totals.get('production', 0)) }}</td>
      </tr>
      {% for row in prod_rows %}
      <tr>
        <td>{{ desc(row) }}</td>
        <td class="c">{{ fmtq(row.get('req_qty', 0)) }}</td>
        <td class="r">{{ fmt(row.get('rate', 0)) if row.get('rate', 0) else '' }}</td>
        <td class="r">{{ fmt(row.get('amount', 0)) }}</td>
      </tr>
      {% endfor %}
      {% endif %}
    </tbody>
  </table>

  {# ─── Summary section ─── #}
  <div class="sum-wrap">
    {# Left — job specs #}
    <div class="sum-left">
      {% if is_flexo %}
        <div>Sticker Size (L * W) : {{ (form.get('product_length_mm', 0) | int) }}*{{ (form.get('product_width_mm', 0) | int) }}</div>
        <div>Ups : {{ sheet.get('ups', 0) | int }}</div>
        <div>Colors : {{ doc.no_of_colors or 0 }}</div>
        <div>Stickers per Reel : {{ sheet.get('stickers_per_reel', 0) | int }}</div>
        <div>Gold Color: {{ 'YES' if has_gold else 'NO' }}, Silver Color : {{ 'YES' if has_silver else 'NO' }}</div>
        <div>Material Width : {{ form.get('reel_width_mm', 0) | int }}</div>
      {% else %}
        {% if doc.carton_size %}<div>Ctn Size : {{ doc.carton_size }}</div>{% endif %}
        {% if form.get('full_sheet_l') %}<div>F.Sheet Size : {{ form.get('full_sheet_l') | int }} x {{ form.get('full_sheet_w') | int }} INCH</div>{% endif %}
        {% if form.get('cut_sheet_l') %}<div>C.Sheet Size : {{ form.get('cut_sheet_l') | int }} x {{ (form.get('cut_sheet_w') or form.get('cut_sheetw') or 0) | int }} INCH</div>{% endif %}
        <div>Ups : {{ sheet.get('cut_sheet_ups', 0) | int }}</div>
        <div>Cuts : {{ doc.no_of_cuts or 0 }}</div>
        <div>Colors : {{ doc.no_of_colors or 0 }}</div>
      {% endif %}
    </div>

    {# Right — pricing summary #}
    <div class="sum-right">
      <table>
        <tr><td>Order Quantity</td><td>{{ item_qty | int }}</td></tr>
        {% if not is_flexo %}
        <tr><td>{{ '{:.2f}%'.format(mat_contrib) }} from Production Cost</td><td>{{ fmt(grand_total * mat_contrib / 100) }}</td></tr>
        {% endif %}
        <tr><td>Total Value</td><td>{{ fmt(grand_total) }}</td></tr>
        <tr><td>Unit Cost</td><td>{{ fmt(unit_cost) }}</td></tr>
        <tr><td>SSCL 2.5 %</td><td>{{ fmt(sscl_amt / item_qty) if item_qty else '0.00' }}</td></tr>
        <tr><td>Profit Margin</td><td>{{ profit_margin | int }} %</td></tr>
        {% if is_flexo %}
        <tr><td>Selling Price</td><td>{{ fmt(sell_total) }}</td></tr>
        {% endif %}
        <tr><td>Quoted Price</td><td>{{ fmt(sell_unit) }}</td></tr>
        <tr><td>VAT 18%</td><td>{{ fmt(vat_amt / item_qty) if item_qty else '0' }}</td></tr>
        <tr class="sum-sep"><td>Final Value</td><td>{{ fmt(sell_unit + (vat_amt / item_qty if item_qty else 0)) }}</td></tr>
        <tr><td>Material Contribution</td><td>{{ fmt(mat_contrib) }}</td></tr>
      </table>
    </div>
  </div>

  {# ─── Remarks ─── #}
  <div class="remarks-lbl">Remarks :</div>
  <div style="margin-left:12px; margin-bottom:12px; font-size:11.5px;">
    {{ form.get('remarks', '') | replace('\n', '<br>') | safe }}
  </div>

  {# ─── Materials table ─── #}
  <div class="remarks-lbl">Materials :</div>
  <table class="mat-tbl">
    <thead>
      <tr>
        <th style="width:40%">Material</th>
        <th>Type</th>
        <th>Quantity</th>
        <th>Tolerance</th>
        <th>Reissue</th>
        <th>Unit</th>
      </tr>
    </thead>
    <tbody>
      <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>
    </tbody>
  </table>
</div>

{% set sp_name = frappe.db.get_value('User', doc.sales_person, 'full_name') or doc.sales_person or '' %}
{% set sp_desig = frappe.db.get_value('User', doc.sales_person, 'designation') or '' %}
{% set ns_i = namespace(names=[]) %}
{% for row in doc.items %}{% if row.item_name and row.item_name not in ns_i.names %}{% set ns_i.names = ns_i.names + [row.item_name] %}{% endif %}{% endfor %}
<style>
